@layer components {
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="content"]) {
    outline-style: none;
  }

  :where([data-control-family="popup"][data-popup-kind="hover-card"][data-slot="positioner"]) {
    outline-style: none;
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="link"]) {
    text-decoration-line: none;
  }

  :where([data-control-family="popup"][data-popup-kind="menubar"][data-slot="sub-trigger-indicator"]) {
    line-height: 1;
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"]) {
    text-align: left;
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-starting-style]) {
    --_popup-rich-tooltip-content-opacity: 0%;
    opacity: var(--_popup-rich-tooltip-content-opacity);
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="content"][data-ending-style]) {
    --_popup-rich-tooltip-content-opacity: 0%;
    opacity: var(--_popup-rich-tooltip-content-opacity);
  }

  :where([data-control-family="popup"][data-popup-kind="rich-tooltip"][data-slot="positioner"]) {
    outline-style: none;
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="content"]) {
    outline-style: none;
  }

  :where([data-control-family="popup"][data-popup-kind="color-picker"][data-slot="positioner"]) {
    outline-style: none;
  }

  :where([data-control-family="popup"][data-popup-kind="context-menu"][data-slot="sub-trigger-indicator"]) {
    line-height: 1;
  }

  :where([data-control-family="button"][data-slot="root"][data-popup-part="close"][data-icon-only="true"]) {
    --_popup-button-root-close-opacity: 70%;
    opacity: var(--_popup-button-root-close-opacity);
  }

  @media (hover: hover) {
    :where([data-control-family="button"][data-slot="root"][data-popup-part="close"][data-icon-only="true"]:hover) {
      --_popup-button-root-close-opacity: 100%;
      opacity: var(--_popup-button-root-close-opacity);
    }
  }
}

@layer components {
  :where([data-control-family="popup"][data-popup-kind="model-switcher"][data-slot="hint"]) {
    margin-inline-start: auto;
    padding-inline-start: calc(var(--spacing) * 4);
    font-size: var(--text-micro);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="group-label"]) {
    padding-block: calc(var(--spacing) * 1) calc(var(--spacing) * 0.5);
    text-transform: uppercase;
    font-size: var(--text-micro);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="empty"]) {
    padding-block: calc(var(--spacing) * 2);
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="icon"]) {
    inline-size: calc(var(--spacing) * 5);
    block-size: calc(var(--spacing) * 5);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="list"]),
  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="group"]) {
    gap: calc(var(--spacing) * 0.5);
  }

  :where([data-control-family="popup"][data-popup-kind="trigger-menu"][data-slot="positioner"]) {
    outline-style: none;
  }

  :where([data-control-family="field"][data-field-kind="combobox"][data-slot="group"]),
  :where([data-control-family="field"][data-field-kind="autocomplete"][data-slot="group"]) {
    padding-block: calc(var(--spacing) * 1);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="group-label"]) {
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="item-indicator"]) {
    color: var(--foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="empty"]) {
    padding-block: calc(var(--spacing) * 6);
    text-align: center;
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="combobox"][data-slot="positioner"]) {
    outline-style: none;
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-chrome="embedded"]) {
    border-radius: inherit;
    corner-shape: inherit;
  }

  :where([data-control-family="popup"][data-popup-kind="command"] > [data-control-family="scroll-area"][data-slot="root"]:last-child) {
    border-radius: inherit;
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="group"] [cmdk-group-heading]) {
    padding-inline: calc(var(--spacing) * 2);
    padding-block: calc(var(--spacing) * 1.5);
    text-transform: uppercase;
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="empty"]) {
    padding-block: calc(var(--spacing) * 6);
    text-align: center;
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input-wrapper"]) {
    border-start-start-radius: inherit;
    border-start-end-radius: inherit;
    gap: calc(var(--spacing) * 2);
    block-size: var(--control-h-lg);
    padding-inline: calc(var(--padding-x) * 1.25);
    border-block-end: 1px solid var(--cui-popup-separator-color);
    font-size: var(--text-body);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input"]) {
    background: transparent;
    color: var(--foreground);
    outline-style: none;
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input"])::placeholder,
  :where([data-control-family="popup"][data-popup-kind="command"] [cmdk-group-heading]) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input"]:disabled) {
    opacity: 0.5;
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="group"]) {
    color: var(--foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="input-icon"]) {
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="dialog-root"]) {
    transition-property: grid-template-rows;
    transition-duration: var(--duration-slow);
    transition-timing-function: var(--ease-emphasized);
    transition-delay: var(--duration-fast);
  }

  :where([data-control-family="popup"][data-popup-kind="autocomplete"][data-slot="group-label"]) {
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="autocomplete"][data-slot="empty"]) {
    padding-block: calc(var(--spacing) * 6);
    text-align: center;
    font-size: var(--text-body);
    color: var(--muted-foreground);
  }

  :where([data-control-family="popup"][data-popup-kind="autocomplete"][data-slot="positioner"]) {
    outline-style: none;
  }

  :where([data-control-family="popup"][data-popup-part="item"] > span:first-child) {
    gap: calc(var(--spacing) * 2);
  }

  :where([data-control-family="popup"][data-popup-part="label"]) {
    padding-block: calc(var(--spacing) * 1);
    padding-inline: calc(var(--padding-x) * 0.5);
    color: var(--muted-foreground);
    font-size: var(--text-micro);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  :where([data-control-family="popup"][data-popup-part="item"][data-inset]),
  :where([data-control-family="popup"][data-popup-part="label"][data-inset]),
  :where([data-control-family="popup"][data-popup-part="item"]:is([data-slot="checkbox-item"], [data-slot="radio-item"])) {
    padding-inline-start: calc(var(--spacing) * 8);
  }

  :where([data-control-family="popup"][data-popup-part="separator"]) {
    margin-block: calc(var(--spacing) * 1);
    margin-inline: calc(var(--popover-padding) * -1);
    block-size: 1px;
    background-color: var(--cui-popup-separator-color);
  }

  :where([data-control-family="popup"][data-popup-part="shortcut"]) {
    margin-inline-start: auto;
    padding-inline-start: calc(var(--spacing) * 6);
    --_popup-shortcut-font-size: var(--text-body);
    color: var(--cui-popup-shortcut-foreground);
    font-size: var(--_popup-shortcut-font-size);
    letter-spacing: 0.02em;
  }

  :where([data-control-family="popup"][data-popup-kind="command"][data-slot="shortcut"]) {
    --_popup-shortcut-font-size: var(--text-label);
  }

  :where([data-control-family="popup"][data-slot="sub-trigger-indicator"]) {
    margin-inline-start: auto;
    padding-inline-start: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-part="bar"]) {
    gap: calc(var(--spacing) * 0.5);
    padding: calc(var(--spacing) * 1);
  }

  :where([data-control-family="popup"][data-popup-kind="navigation-menu"][data-slot="list"]) {
    gap: calc(var(--spacing) * 0.5);
  }

  :where([data-control-family="popup"][data-popup-part="navigation-link"]) {
    padding-block: calc(var(--spacing) * 2);
    padding-inline: calc(var(--spacing) * 3);
  }

  :where([data-control-family="popup"][data-popup-part="navigation-link"][data-variant="compact"]) {
    padding-block: 0;
  }
}

@layer components {
  :where([data-control-family="popup"][data-popup-kind="sheet"][data-popup-part="surface"]) {
    outline-style: none;
    transition-property: translate;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
    border-radius: 0;
    border-style: solid;
    border-width: 0px;
  }

  :where(
    [data-control-family="popup"][data-popup-kind="sheet"][data-popup-part="surface"][data-side="left"]:is(
      [data-starting-style],
      [data-ending-style]
    )
  ) {
    translate: -100% 0;
  }

  :where(
    [data-control-family="popup"][data-popup-kind="sheet"][data-popup-part="surface"][data-side="right"]:is(
      [data-starting-style],
      [data-ending-style]
    )
  ) {
    translate: 100% 0;
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="arrow-shape"]) {
    fill: currentcolor;
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"]) {
    font-size: var(--text-xs);
    line-height: var(--text-xs--line-height);
    text-wrap: balance;
    outline-style: none;
    --_popup-tooltip-content-transition-property: opacity, scale;
    transition-property: var(--_popup-tooltip-content-transition-property);
    transition-timing-function: var(--ease-standard);
    transition-duration: var(--duration-fast);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-instant]) {
    --_popup-tooltip-content-transition-property: none;
    transition-property: var(--_popup-tooltip-content-transition-property);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-ending-style]) {
    --_popup-tooltip-content-opacity: 0%;
    opacity: var(--_popup-tooltip-content-opacity);
    --_popup-tooltip-content-scale: 95% 95%;
    scale: var(--_popup-tooltip-content-scale);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-starting-style]) {
    --_popup-tooltip-content-opacity: 0%;
    opacity: var(--_popup-tooltip-content-opacity);
    --_popup-tooltip-content-scale: 95% 95%;
    scale: var(--_popup-tooltip-content-scale);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="positioner"]) {
    outline-style: none;
  }

  :where(
    [data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-popup-part="surface"]:not([data-arrow="true"])
  ) {
    --_popup-tooltip-content-radius: var(--cui-popup-radius);
    border-radius: var(--_popup-tooltip-content-radius);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"][data-popup-part="surface"][data-arrow="true"]) {
    --_popup-tooltip-content-radius: clamp(0px, var(--cui-popup-radius), 3px);
    border-radius: var(--_popup-tooltip-content-radius);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="arrow"][data-side="top"]) {
    --_popup-tooltip-arrow-rotate: 180deg;
    rotate: var(--_popup-tooltip-arrow-rotate);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="arrow"][data-side="left"]) {
    --_popup-tooltip-arrow-rotate: 90deg;
    rotate: var(--_popup-tooltip-arrow-rotate);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="arrow"][data-side="right"]) {
    --_popup-tooltip-arrow-rotate: calc(90deg * -1);
    rotate: var(--_popup-tooltip-arrow-rotate);
  }
}

@layer components {
  :where([data-control-family="popup"][data-popup-part="surface"]),
  :where([data-control-family="popup"][data-popup-part="list-surface"]),
  :where([data-control-family="popup"][data-popup-part="bar"]) {
    --cui-popup-radius: var(--radius-popover);
    --cui-popup-background: var(--popover);
    --cui-popup-foreground: var(--popover-foreground);
    --cui-popup-border-color: var(--control-rim);
    --cui-popup-border-width: var(--control-rim-width);
    --cui-popup-shadow: var(--shadow-pop);
    --cui-popup-backdrop-filter: blur(var(--backdrop-blur-popover));
    --cui-popup-item-radius: var(--radius-popup-item-fit);
    --cui-popup-item-foreground: var(--foreground);
    --cui-popup-item-highlight-background: var(--hover-fill);
    --cui-popup-item-highlight-foreground: var(--cui-popup-item-foreground);
    --cui-popup-item-highlight-muted-foreground: var(--muted-foreground);
    --cui-popup-item-disabled-opacity: 0.4;
    --cui-popup-separator-color: var(--border);
    --cui-popup-shortcut-foreground: var(--muted-foreground);
    --_popup-transform-origin: var(--transform-origin);
    border-radius: var(--cui-popup-radius);
    background-color: var(--cui-popup-background);
    box-shadow:
      inset 0 0 0 var(--cui-popup-border-width) var(--cui-popup-border-color),
      var(--cui-popup-shadow);
    color: var(--cui-popup-foreground);
    outline: none;
    -webkit-backdrop-filter: var(--cui-popup-backdrop-filter, none);
    backdrop-filter: var(--cui-popup-backdrop-filter, none);
    transform-origin: var(--_popup-transform-origin);
  }
  :where([data-control-family="popup"][data-popup-part="surface"]:not([data-popup-static]):not([data-slot="viewport"])),
  :where([data-control-family="popup"][data-popup-part="list-surface"]) {
    transition-property: opacity, scale;
    transition-duration: var(--duration-base);
    transition-timing-function: var(--ease-emphasized);
    transition-behavior: allow-discrete;
  }
  :where(
    [data-control-family="popup"][data-popup-part="surface"]:not(
      :is([data-popup-kind="sheet"], [data-popup-kind="drawer"], [data-popup-kind="toast"])
    ):not([data-slot="viewport"]):where([data-starting-style], [data-ending-style])
  ),
  :where([data-control-family="popup"][data-popup-part="list-surface"]:where([data-starting-style], [data-ending-style])) {
    scale: 0.95;
    opacity: 0;
  }
  @starting-style {
    :where(
        [data-control-family="popup"][data-popup-part="surface"]:not(
          :is([data-popup-kind="sheet"], [data-popup-kind="drawer"], [data-popup-kind="toast"])
        ):not([data-slot="viewport"])
      ),
    :where([data-control-family="popup"][data-popup-part="list-surface"]) {
      scale: 0.95;
      opacity: 0;
    }
  }
  :where([data-control-family="popup"][data-popup-part="backdrop"]) {
    --cui-popup-backdrop-background: oklch(from var(--foreground) l c h / var(--overlay-opacity));
    background-color: var(--cui-popup-backdrop-background);
    --cui-popup-backdrop-blur: blur(var(--backdrop-blur-overlay));
    -webkit-backdrop-filter: var(--cui-popup-backdrop-blur);
    backdrop-filter: var(--cui-popup-backdrop-blur);
    transition: opacity var(--duration-base) var(--ease-emphasized);
  }
  :where(.dark [data-control-family="popup"][data-popup-part="backdrop"]) {
    --cui-popup-backdrop-background: oklch(from var(--background) l c h / var(--overlay-opacity));
  }
  :where([data-control-family="popup"][data-popup-part="backdrop"]:is([data-starting-style], [data-ending-style])) {
    opacity: 0;
  }
  :where([data-control-family="popup"][data-popup-part="list-surface"]) {
    padding: var(--popover-padding);
  }
  :where([data-control-family="popup"][data-popup-part="bar"]) {
    --cui-popup-radius: var(--radius-control);
    --cui-popup-background: var(--card);
    --cui-popup-shadow: var(--shadow-xs);
  }
  :where([data-control-family="popup"][data-popup-part="surface"][data-surface="modal"]) {
    --cui-popup-radius: var(--radius-panel);
    --cui-popup-shadow: var(--shadow-modal);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-popup-part="surface"]) {
    --cui-popup-radius: var(--radius-control);
    --cui-popup-background: var(--foreground);
    --cui-popup-foreground: var(--background);
  }

  :where([data-control-family="popup"][data-popup-kind="sheet"][data-popup-part="surface"]) {
    --cui-popup-radius: 0px;
    --cui-popup-shadow: var(--shadow-modal);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="title"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="title"]) {
    font-size: var(--text-heading-3);
    font-weight: var(--font-weight-semibold);
    line-height: 1;
    letter-spacing: -0.025em;
    text-wrap: balance;
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="description"]),
  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-body);
    text-wrap: pretty;
  }

  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="title"]) {
    font-weight: var(--font-weight-semibold);
    text-wrap: balance;
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="arrow"]) {
    color: var(--cui-popup-background);
  }

  :where([data-control-family="popup"][data-popup-kind="tooltip"][data-slot="content"]) {
    padding: calc(var(--spacing) * 1) calc(var(--spacing) * 2.5);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="content"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="content"]),
  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="content"]) {
    gap: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="header"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding: calc(var(--spacing) * 4) calc(var(--spacing) * 4) 0;
  }

  :where([data-control-family="popup"][data-popup-kind="dialog"][data-slot="footer"]),
  :where([data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="footer"]) {
    gap: calc(var(--spacing) * 2);
    padding: 0 calc(var(--spacing) * 4) calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="sheet"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-kind="popover"][data-slot="header"]) {
    gap: calc(var(--spacing) * 1.5);
    padding-block-end: calc(var(--spacing) * 3);
  }

  :where([data-control-family="popup"][data-popup-kind="popover"][data-popup-part="surface"][data-padding="default"]),
  :where([data-control-family="popup"][data-popup-kind="hover-card"][data-popup-part="surface"]) {
    padding: calc(var(--spacing) * 4);
  }

  :where([data-control-family="popup"][data-popup-part="item"]) {
    gap: calc(var(--spacing) * 2);
    min-block-size: var(--control-h-xs);
  }

  :where([data-control-family="popup"][data-popup-part="item"]),
  :where([data-control-family="popup"][data-popup-part="navigation-link"]) {
    cursor: pointer;
    border-radius: var(--cui-popup-item-radius);
    color: var(--cui-popup-item-foreground);
    font-size: var(--text-body);
    outline: none;
    padding-block: calc(var(--spacing) * 1);
    padding-inline: calc(var(--padding-x) * 0.5);
  }

  :where([data-control-family="popup"][data-popup-part="navigation-link"]) {
    font-size: var(--text-body);
    transition-property: translate;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-standard);
  }

  :where([data-control-family="popup"][data-popup-part="navigation-link"][data-variant="compact"]) {
    color: var(--muted-foreground);
    font-size: var(--text-label);
    font-weight: var(--font-weight-medium);
  }

  :where([data-control-family="popup"][data-popup-part="navigation-link"]:where(:hover, :focus-visible, [data-active])) {
    background-color: var(--cui-popup-item-highlight-background);
    color: var(--foreground);
  }

  :where(
    [data-control-family="popup"][data-popup-part="item"]:where(
      [data-highlighted],
      [data-selected]:not([data-selected="false"]),
      [data-popup-open]
    )
